def main():
 (OUT/'reviewed-recipes.jsonl').write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in R))
 with (OUT/'reviewed-recipes.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=R[0]);w.writeheader();w.writerows({k:json.dumps(v,ensure_ascii=False) if isinstance(v,list) else v for k,v in r.items()} for r in R)
if __name__=='__main__':main()
